BEGIN;
CREATE TABLE IF NOT EXISTS feed_usage(id uuid PRIMARY KEY,cycle_id uuid NOT NULL REFERENCES production_cycles(id),usage_date date NOT NULL,item_id uuid REFERENCES item_master(id),quantity_kg numeric(18,3) NOT NULL CHECK(quantity_kg>=0),source varchar(20) NOT NULL DEFAULT 'CONTRACT' CHECK(source IN('CONTRACT','EXTRA')),notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS abk_work_entries(id uuid PRIMARY KEY,cycle_id uuid NOT NULL REFERENCES production_cycles(id),work_date date NOT NULL,worker_name varchar(160) NOT NULL,work_type varchar(80) NOT NULL,quantity numeric(18,3) NOT NULL DEFAULT 0 CHECK(quantity>=0),rate numeric(18,2) NOT NULL DEFAULT 0 CHECK(rate>=0),amount numeric(18,2) GENERATED ALWAYS AS (quantity*rate) STORED,notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS extra_sapronak(id uuid PRIMARY KEY,cycle_id uuid NOT NULL REFERENCES production_cycles(id),item_id uuid REFERENCES item_master(id),expense_date date NOT NULL,quantity numeric(18,3) NOT NULL CHECK(quantity>=0),unit_price numeric(18,2) NOT NULL CHECK(unit_price>=0),amount numeric(18,2) GENERATED ALWAYS AS (quantity*unit_price) STORED,notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
